По **[STATE] EXECUTION** нельзя делать `TRANSITION: done` (запрещён переход `execution→done`). После реализации шага — **`TRANSITION: validation`**, затем на validation — тесты и refresh/validation по плану.

---

## `src/jwt.js`

```javascript
import jwt from 'jsonwebtoken';
import { getEnv } from './env.js';

const DEFAULT_ACCESS_TTL = '15m';
const DEFAULT_REFRESH_TTL = '7d';

function secret(kind) {
  const env = getEnv();
  if (kind === 'refresh') {
    return env.JWT_REFRESH_SECRET ?? env.JWT_SECRET;
  }
  return env.JWT_SECRET;
}

function ttl(kind) {
  const env = getEnv();
  if (kind === 'refresh') {
    return env.JWT_REFRESH_TTL ?? DEFAULT_REFRESH_TTL;
  }
  return env.JWT_ACCESS_TTL ?? DEFAULT_ACCESS_TTL;
}

/** @param {Record<string, unknown>} payload @param {{ expiresIn?: string }} [options] */
export function signAccessToken(payload, options = {}) {
  return jwt.sign(payload, secret('access'), {
    expiresIn: options.expiresIn ?? ttl('access'),
  });
}

/** @param {Record<string, unknown>} payload @param {{ expiresIn?: string }} [options] */
export function signRefreshToken(payload, options = {}) {
  return jwt.sign(
    { ...payload, typ: 'refresh' },
    secret('refresh'),
    { expiresIn: options.expiresIn ?? ttl('refresh') },
  );
}

/** @param {string} token @param {{ ignoreExpiration?: boolean }} [options] */
export function verifyAccessToken(token, options = {}) {
  const decoded = jwt.verify(token, secret('access'), {
    ignoreExpiration: Boolean(options.ignoreExpiration),
  });
  if (decoded && typeof decoded === 'object' && decoded.typ === 'refresh') {
    throw new jwt.JsonWebTokenError('expected access token');
  }
  return decoded;
}

/** @param {string} token @param {{ ignoreExpiration?: boolean }} [options] */
export function verifyRefreshToken(token, options = {}) {
  const decoded = jwt.verify(token, secret('refresh'), {
    ignoreExpiration: Boolean(options.ignoreExpiration),
  });
  if (!decoded || typeof decoded !== 'object' || decoded.typ !== 'refresh') {
    throw new jwt.JsonWebTokenError('expected refresh token');
  }
  const { typ, ...rest } = decoded;
  return rest;
}

/** @param {string} refreshToken */
export function refreshAccessToken(refreshToken) {
  const payload = verifyRefreshToken(refreshToken);
  const { iat, exp, nbf, ...claims } = payload;
  return signAccessToken(claims);
}

export { jwt as jsonwebtoken };
```

---

## Зависимость

В `package.json`:

```json
"dependencies": {
  "jsonwebtoken": "^9.0.2"
}
```

---

## `.env.example` (фрагмент)

```env
JWT_SECRET=change-me-access-secret-min-32-chars
JWT_REFRESH_SECRET=change-me-refresh-secret-min-32-chars
JWT_ACCESS_TTL=15m
JWT_REFRESH_TTL=7d
```

В `src/env.js` должны читаться `JWT_SECRET` (обязательно), опционально `JWT_REFRESH_SECRET`, `JWT_ACCESS_TTL`, `JWT_REFRESH_TTL`.

---

## Поведение модуля

| Функция | Назначение |
|--------|------------|
| `signAccessToken` | access JWT без `typ: refresh` |
| `signRefreshToken` | refresh JWT с `typ: 'refresh'`, отдельный секрет |
| `verifyAccessToken` | проверка access, отклонение refresh-токена |
| `verifyRefreshToken` | проверка refresh, возврат claims без `typ` |
| `refreshAccessToken` | новый access из валидного refresh |

---

